export const TOOL_DEFINITIONS = [...FULL_TOOL_DEFINITIONS.map(tool => ({ ...tool, description: toolSummaries[tool.name] ?? tool.description, inputSchema: conciseSchema(tool.inputSchema) as typeof tool.inputSchema })),
    { name: 'director_help', description: 'Read one topic or 1-3 named tool contracts. Topics: editing/camera/media/physics/files/extensions/production/project. Named director_apply returns basic syntax and topic index; full:true explicitly returns its complete legacy contract. Use topic OR names.', inputSchema: schema({ names: { type: 'array', items: string, minItems: 1, maxItems: 3 }, topic: { type: 'string', enum: Object.keys(HELP_TOPICS) }, full: { type: 'boolean' } }) },
];
// Share concise discovery; advanced contracts remain available through director_help.
export const MCP_TOOL_DEFINITIONS = TOOL_DEFINITIONS;
export function toolHelp(names?: string[], options: { topic?: string; full?: boolean } = {}) {
    if (options.topic !== undefined) {
        if (names !== undefined || options.full !== undefined) throw Error('主题帮助使用 topic；工具契约使用 names 和可选 full');
        return { tools: [], guide: topicHelp(options.topic) };
    }
    if (!names?.length) throw Error('请提供 names 或 topic');
    return { tools: names.map(name => {
        const tool = FULL_TOOL_DEFINITIONS.find(t => t.name === name);
        if (!tool) throw Error('未知帮助工具：' + name);
        return name === 'director_apply' && options.full !== true
            ? { ...structuredClone(tool), description: toolSummaries.director_apply, topics: HELP_TOPICS }
            : structuredClone(tool);
    }) };
}
const mediaReadActions=['list','surfaces'];
const sceneReadActions = ['list', 'read'];
const discussionNames = new Set(['director_skill', 'director_help', 'director_nodes', 'director_path_surface', 'director_stride', 'director_read', 'director_assets', 'director_motions', 'director_spatial', 'director_continuity']);
// Mixed query/edit tools expose only their read operations in discussion mode.
// The host also applies this policy at execution: a provider can ignore a schema.
export const DISCUSSION_TOOLS = TOOL_DEFINITIONS.filter(tool => ['director_versions','director_plugins','director_settings','director_motion_library','director_application'].includes(tool.name) || tool.name === 'director_staging' || tool.name === 'director_media' || tool.name === 'director_scene' || discussionNames.has(tool.name)).map(tool => {
    if(tool.name==='director_versions')return {...tool,inputSchema:schema({action:{type:'string',enum:['list']}},['action'])};
    if(tool.name==='director_plugins')return {...tool,inputSchema:schema({action:{type:'string',enum:['list','read']},id:string},['action'])};
    if(tool.name==='director_settings')return {...tool,description:'Read local editor/file/layout/asset preferences.',inputSchema:schema({scope:{type:'string',enum:['editor','files','layout','assets']},action:{type:'string',enum:['read']}},['scope','action'])};
    if(tool.name==='director_motion_library')return {...tool,description:'Read one user motion; optional details returns source rig inspection.',inputSchema:schema({action:{type:'string',enum:['read']},id:string,details:{type:'boolean'}},['action','id'])};
    if(tool.name==='director_application')return {...tool,description:'Read local skills or updater state without changes.',inputSchema:schema({scope:{type:'string',enum:['skills','updates']},action:{type:'string',enum:['list','read','state']},data:object},['scope','action'])};
    if(tool.name==='director_staging')return {...tool,description:'Query saved staging metadata or member summaries without modifying the scene or library.',inputSchema:schema({action:{type:'string',enum:['list','read']},id:string,query:string,offset:number,limit:number},['action'])};
    if(tool.name==='director_media')return {...tool,description:'List imported media or inspect mesh/material surface indexes.',inputSchema:schema({action:{type:'string',enum:mediaReadActions},entityId:string},['action'])};
    if (tool.name === 'director_scene') return { ...tool,
        description: 'Read independent scenes: list returns IDs and context; read defaults to object summaries. Use sections/ids/details for selected content. Query only; director_continuity reads the saved predecessor ending.',
        inputSchema: schema({ action: { type: 'string', enum: sceneReadActions }, sceneId: string, sections:{type:'array',items:{type:'string',enum:[...SAVED_SCENE_SECTIONS,'all']}}, ids:{type:'array',items:string}, details:{type:'boolean'} }, ['action']),
    };
    return tool;
});
export function isDiscussionToolCall(name: string, args: unknown): boolean {
    if(name==='director_versions'||name==='director_plugins'){const a=args as Record<string,unknown>|null;return !!a&&!Array.isArray(a)&&(a.action==='list'||name==='director_plugins'&&a.action==='read')&&Object.keys(a).every(k=>['action','id'].includes(k));}
    if(['director_settings','director_motion_library','director_application'].includes(name)){if(!args||typeof args!=='object'||Array.isArray(args))return false;const a=args as Record<string,unknown>;const allowed=name==='director_settings'?['scope','action']:name==='director_motion_library'?['action','id','details']:['scope','action','data'];return ['read','list','state'].includes(String(a.action))&&Object.keys(a).every(k=>allowed.includes(k));}
    if(name==='director_staging'){const a=args as Record<string,unknown>|null;return !!a&&['list','read'].includes(String(a.action))&&Object.keys(a).every(k=>['action','id','query','offset','limit'].includes(k));}
    if(name==='director_media'){const a=args as Record<string,unknown>|null;return !!a&&mediaReadActions.includes(String(a.action))&&Object.keys(a).every(k=>k==='action'||k==='entityId');}
    if (name !== 'director_scene') return discussionNames.has(name);
    if (!args || typeof args !== 'object' || Array.isArray(args)) return false;
    const input = args as Record<string, unknown>;
    return typeof input.action === 'string' && sceneReadActions.includes(input.action)
        && Object.keys(input).every(key => ['action','sceneId','sections','ids','details'].includes(key));
}
